#include <cmath>
#include <cstdio>
#include <vector>
#include "Biquad.h"
#include "Filters.h"
#include "InputRolloff.h"
using namespace ssle;
static const double FS=48000.0;
struct D{double b0,b1,b2,a1,a2;};
static D fromF(BiquadCoeffs k){return {k.b0,k.b1,k.b2,k.a1,k.a2};}
// render one section (or cascade of 2) with float state, accumulate DTFT at 10 Hz, N frames
double renderF32(D c, D c2, bool two, int N, double hz, double* zratio){
  float z1=0,z2=0,w1=0,w2=0; double re=0,im=0; double w=-2*M_PI*hz/FS;
  double maxz=0, lasty=0;
  for(int n=0;n<N;++n){
    float x = n==0?1.f:0.f;
    float o=(float)(c.b0*(double)x + z1); z1=(float)(c.b1*(double)x - c.a1*(double)o + z2); z2=(float)(c.b2*(double)x - c.a2*(double)o);
    if(two){ float y1=o; o=(float)(c2.b0*(double)y1 + w1); w1=(float)(c2.b1*(double)y1 - c2.a1*(double)o + w2); w2=(float)(c2.b2*(double)y1 - c2.a2*(double)o); }
    if(fabs((double)z1) > maxz) maxz=fabs((double)z1);
    lasty=o;
    re+=o*cos(w*n); im+=o*sin(w*n);
  }
  if(zratio) *zratio = maxz;
  return hypot(re,im);
}
int main(){
  BiquadTarget roll; roll.type=BiquadType::Highpass; roll.freqHz=InputRolloff::kCornerHz; roll.q=InputRolloff::kQ;
  D R=fromF(designBiquad(roll,FS));
  BiquadTarget t; t.type=BiquadType::Highpass; t.freqHz=23.1; t.q=0.70710678118654752440;
  D H=fromF(designBiquad(t,FS));
  double closedR=biquadMagnitudeAt(designBiquad(roll,FS),10.0,FS);
  double closedRH=biquadMagnitudeAt(designBiquad(roll,FS),10.0,FS)*biquadMagnitudeAt(designBiquad(t,FS),10.0,FS);
  printf("closed: roll %.6f dB, roll*hp %.6f dB\n", 20*log10(closedR), 20*log10(closedRH));
  for(int N : {2048, 8192, 65536, 262144}) {
    double zr=0;
    double a=renderF32(R,R,false,N,10.0,&zr);
    double b=renderF32(R,H,true,N,10.0,&zr);
    printf("N=%7d  roll %.4f dB (err %+.4f)  cascade %.4f dB (err %+.4f)  ratio %.4f dB  max|z1|=%.3g\n",
      N, 20*log10(a), 20*log10(a)-20*log10(closedR), 20*log10(b), 20*log10(b)-20*log10(closedRH),
      20*log10(b/a), zr);
  }
  // where does the state sit relative to the output? report |z1|/|y| for the rolloff driven by an impulse
  {
    float z1=0,z2=0; double w=-2*M_PI*10.0/FS;
    printf("\n n     y(float)      z1(next)      |z1|/|y|\n");
    for(int n=0;n<24;++n){
      float x=n==0?1.f:0.f;
      float o=(float)(R.b0*(double)x+z1);
      z1=(float)(R.b1*(double)x - R.a1*(double)o + z2); z2=(float)(R.b2*(double)x - R.a2*(double)o);
      printf("%3d %14.8g %14.8g %10.3g\n", n, o, z1, o!=0?fabs((double)z1/o):0.0);
    }
  }
  return 0;
}
EOF
