// Baseline algorithm extracted verbatim from git HEAD:midi/MidiPort.mm (feed(), the
// block at :144-201) with the mutex/callback plumbing removed. Used only to show what
// the old code did for the two inputs tests/midi_module_test.cpp now pins.
#include <cstdint>
#include <cstdio>
#include <vector>

struct OldParser
{
    std::vector<std::vector<uint8_t>> sysexFrames;
    std::vector<uint8_t> sysexBuf;
    bool    inSysex   = false;
    uint8_t status    = 0;
    uint8_t data[2]   = { 0, 0 };
    int     dataCount = 0;
    int     channelMessages = 0;

    int bytesNeeded (uint8_t s)
    {
        switch (s & 0xF0)
        {
            case 0xC0: case 0xD0: return 1;
            case 0x80: case 0x90: case 0xA0: case 0xB0: case 0xE0: return 2;
            default: return 0;
        }
    }

    void feed (const uint8_t* d, size_t n)
    {
        // ---- begin: verbatim from HEAD:midi/MidiPort.mm:144-201 ----
        for (size_t i = 0; i < n; ++i)
        {
            const uint8_t b = d[i];
            if (b >= 0xF8) continue;
            if (b == 0xF0)
            {
                sysexBuf.clear();
                sysexBuf.push_back (0xF0);
                inSysex = true;
                dataCount = 0;
                continue;
            }
            if (inSysex)
            {
                sysexBuf.push_back (b);
                if (b == 0xF7)
                {
                    inSysex = false;
                    sysexFrames.push_back (sysexBuf);
                    sysexBuf.clear();
                }
                continue;
            }
            if (b & 0x80)
            {
                status    = b;
                dataCount = 0;
                if ((b & 0xF0) == 0xF0) status = 0;
                continue;
            }
            if (status == 0) continue;
            const int need = bytesNeeded (status);
            if (need == 0) { status = 0; continue; }
            data[dataCount++] = b;
            if (dataCount >= need)
            {
                ++channelMessages;
                dataCount = 0;
            }
        }
        // ---- end verbatim ----
    }
};

int main()
{
    int failures = 0;
    {
        OldParser p;
        const uint8_t stream[] = { 0xF0, 0x01, 0x02, 0x90, 0x3C, 0x40 };
        p.feed (stream, sizeof stream);
        std::printf ("lost-F7: frames=%zu channelMessages=%d inSysEx=%d pending=%zu\n",
                     p.sysexFrames.size(), p.channelMessages, (int) p.inSyssex_placeholder(),
                     p.sysexBuf.size());
        if (p.channelMessages != 1) { std::printf ("  DEFECT: the note-on after a lost terminator is swallowed\n"); ++failures; }
        if (p.sysexBuf.size() != 1) { std::printf ("  DEFECT: the dead frame keeps absorbing bytes\n"); ++failures; }
    }
    {
        OldParser p;
        const uint8_t f0 = 0xF0;
        p.feed (&f0, 1);
        std::vector<uint8_t> block (1024, 0x11);
        for (int i = 0; i < 200; ++i) p.feed (block.data(), block.size());
        std::printf ("unbounded: pending=%zu bytes (cap is 65536), inSysEx=%d\n",
                     p.sysexBuf.size(), (int) p.sysexBuf.size());
        if (p.sysexBuf.size() > 65536) { std::printf ("  DEFECT: no bound on the partial frame\n"); ++failures; }
    }
    return failures == 0 ? 0 : 1;
}
