    // smallest legal payload: 32 bytes; header + payload= hex
    std::string hex;
    for (int i = 0; i < 32; ++i) { char b[3]; std::snprintf(b, sizeof b, "%02x", i); hex += b; }
    const char* cases[] = {
        "flag=abc",
        "flag=999",
        "nymphes-preset\npayload=", // no hex
    };
    for (auto* c : cases) {
        std::string t = std::string("nymphes-preset\n") + c + "\n";
        Preset p; std::string e;
        try {
            bool ok = Preset::fromText(t, p, &e);
            std::printf("case [%s] -> ok=%d err=%s\n", c, (int) ok, e.c_str());
        } catch (const std::exception& ex) {
            std::printf("case [%s] -> THREW %s\n", c, ex.what());
        }
    }
    // a param line with a non-numeric value
    std::string t = std::string("nymphes-preset\npayload=") + hex + "\nmain.cut=abc\n";
    Preset p; std::string e;
    try { bool ok = Preset::fromText(t, p, &e); std::printf("cut=abc -> ok=%d err=%s\n", (int) ok, e.c_str()); }
    catch (const std::exception& ex) { std::printf("cut=abc -> THREW %s\n", ex.what()); }
    return 0;
}
