#include <initializer_list>
#include <cstdio>
#include <cmath>
#include <vector>
#include <algorithm>
#include "ChannelStrip.h"
#include "InputRolloff.h"
using namespace ssle;
static void run(double f, bool rolloffOn){
  const int N=96000; std::vector<float> in(N), out(N,0.f);
  for(int i=0;i<N;i++) in[i]=std::sin(2*M_PI*f*i/48000.0);
  ChannelStrip s; EngineParams p=defaultEngineParams(); p.levelDb=0; p.outputDb=0;
  s.setInputRolloffEnabled(rolloffOn);
  s.prepare(48000.0,512); s.setParams(p); s.reset();
  for(int off=0;off<N;off+=512){int len=std::min(512,N-off); const float* ip[2]={in.data()+off,nullptr}; float* op[2]={out.data()+off,nullptr}; s.processPlanar(ip,op,1,len);}
  // DFT over the second half at exactly f (integer cycles when f*48000/48000 = f cycles)
  double re=0,im=0;
  for(int i=48000;i<N;i++){ double ph=2*M_PI*f*i/48000.0; re+=out[i]*std::cos(ph); im+=out[i]*std::sin(ph); }
  const double amp = 2.0*std::hypot(re,im)/48000.0;
  std::printf("f=%7.1f rolloff=%d  amp=%.9f (%.6f dB)\n", f, (int)rolloffOn, amp, 20*std::log10(amp));
}
int main(){
  InputRolloff r; r.prepare(48000.0);
  for(double f : {100.0,1000.0,10000.0}){
    run(f,true); run(f,false);
    std::printf("         rolloff design |H|=%.9f (%.6f dB)\n", r.magnitudeAt(f), 20*std::log10(r.magnitudeAt(f)));
  }
}
